std::vector<std::uint8_t> logon_sid(){win::Handle token;HANDLE raw=nullptr;CHECK(OpenProcessToken(GetCurrentProcess(),TOKEN_QUERY,&raw));token.reset(raw);DWORD size=0;GetTokenInformation(token.get(),TokenLogonSid,nullptr,0,&size);std::vector<std::uint8_t> info(size);CHECK(GetTokenInformation(token.get(),TokenLogonSid,info.data(),size,&size));auto groups=reinterpret_cast<TOKEN_GROUPS*>(info.data());CHECK(groups->GroupCount==1&&(groups->Groups[0].Attributes&SE_GROUP_LOGON_ID)==SE_GROUP_LOGON_ID);auto sid=groups->Groups[0].Sid;std::vector<std::uint8_t> copy(GetLengthSid(sid));CHECK(CopySid(static_cast<DWORD>(copy.size()),copy.data(),sid));return copy;}
