 {Parent p;p.hello();const auto n=static_cast<std::uint32_t>(p.config.wire.frame_bytes+1);std::array<std::uint8_t,4> prefix{static_cast<std::uint8_t>(n>>24),static_cast<std::uint8_t>(n>>16),static_cast<std::uint8_t>(n>>8),static_cast<std::uint8_t>(n)};win::write_exact(p.pipe.get(),p.child.process.get(),prefix,win::Deadline::after(1000),p.config.runtime.cancel_drain_timeout_ms());p.failed();}
 {Parent p;p.hello();std::array<std::uint8_t,5> truncated{0,0,0,20,1};win::write_exact(p.pipe.get(),p.child.process.get(),truncated,win::Deadline::after(1000),p.config.runtime.cancel_drain_timeout_ms());p.pipe.reset();p.failed();}
 {Parent p;p.hello();const std::array<std::uint8_t,1> partial{0};win::write_exact(p.pipe.get(),p.child.process.get(),partial,win::Deadline::after(1000),p.config.runtime.cancel_drain_timeout_ms());p.failed();}
