int parent_death_helper(wchar_t**argv){Parent parent;parent.hello();win::Handle ready(reinterpret_cast<HANDLE>(std::stoull(argv[2]))),stop(reinterpret_cast<HANDLE>(std::stoull(argv[3]))),mapping(reinterpret_cast<HANDLE>(std::stoull(argv[4])));auto view=MapViewOfFile(mapping.get(),FILE_MAP_WRITE,0,0,sizeof(HelperPublication));CHECK(view);*static_cast<HelperPublication*>(view)={parent.child.pid,reinterpret_cast<std::uintptr_t>(parent.pipe.get())};UnmapViewOfFile(view);CHECK(SetEvent(ready.get()));CHECK(WaitForSingleObject(stop.get(),parent.config.runtime.process_exit_timeout_ms())==WAIT_OBJECT_0);ExitProcess(0);}
void actual_parent_death_with_pipe_retained(){
 SECURITY_ATTRIBUTES sa{sizeof(sa),nullptr,TRUE};win::Handle ready(CreateEventW(&sa,TRUE,FALSE,nullptr)),stop(CreateEventW(&sa,TRUE,FALSE,nullptr)),mapping(CreateFileMappingW(INVALID_HANDLE_VALUE,&sa,PAGE_READWRITE,0,sizeof(HelperPublication),nullptr));CHECK(ready&&stop&&mapping);Child helper;wchar_t self[MAX_PATH]{};CHECK(GetModuleFileNameW(nullptr,self,MAX_PATH));HANDLE inherited[]={ready.get(),stop.get(),mapping.get()};helper.launch(self,L"--parent-death-helper "+number(ready.get())+L" "+number(stop.get())+L" "+number(mapping.get()),inherited);CHECK(WaitForSingleObject(ready.get(),configuration().runtime.connect_timeout_ms())==WAIT_OBJECT_0);
 auto view=MapViewOfFile(mapping.get(),FILE_MAP_READ,0,0,sizeof(HelperPublication));CHECK(view);const auto published=*static_cast<const HelperPublication*>(view);UnmapViewOfFile(view);Child engine;engine.pid=published.child_pid;engine.process.reset(OpenProcess(SYNCHRONIZE|PROCESS_QUERY_LIMITED_INFORMATION|PROCESS_TERMINATE,FALSE,published.child_pid));CHECK(engine.process);HANDLE retained=nullptr;CHECK(DuplicateHandle(helper.process.get(),reinterpret_cast<HANDLE>(published.pipe_handle),GetCurrentProcess(),&retained,0,FALSE,DUPLICATE_SAME_ACCESS));win::Handle live_pipe(retained);CHECK(SetEvent(stop.get()));CHECK(helper.wait()==0);CHECK(engine.wait()!=0); // Kept server handle rules out pipe-EOF as the reason for idle child exit; no job exists.
}
