int wmain(int argc,wchar_t**argv){try{if(argc==3&&std::wstring_view(argv[1])==L"--wait-helper"){win::Handle event(reinterpret_cast<HANDLE>(std::stoull(argv[2])));return WaitForSingleObject(event.get(),configuration().runtime.process_exit_timeout_ms())==WAIT_OBJECT_0?0:1;}if(argc==5&&std::wstring_view(argv[1])==L"--parent-death-helper")return parent_death_helper(argv);CHECK(argc==1);const std::pair<const char*,void(*)()>tests[]={{"actual World, ACL, read-only inheritance, PID and fragmentation",actual_world_acl_and_fragmentation},{"invalid CLI, bootstrap, pairing and server PID",invalid_launch_and_pairing},{"oversize, EOF and stalled pending-read cancellation",malformed_and_cancelled_frames},{"Ready idle and bounded first Hello",ready_idle_and_hello_deadlines},{"actual parent death while outer retains pipe",actual_parent_death_with_pipe_retained}};int failures=0;for(auto[name,run]:tests){try{run();std::printf("PASS %s\n",name);}catch(const win::Fault&e){++failures;std::printf("FAIL %s phase=%s code=%lu\n",name,e.phase,e.code);}catch(const std::exception&e){++failures;std::printf("FAIL %s %s\n",name,e.what());}}std::printf("%zu actual-process cases, %d failed\n",std::size(tests),failures);return failures?1:0;}catch(const std::exception&e){std::fprintf(stderr,"Process fixture failure: %s\n",e.what());return 1;}}
